package com.elis.lila;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;
public class AlarmReceiver extends BroadcastReceiver {
 static final String ACTION="com.elis.lila.ALARM";
 static int idFor(int day,String id){return (day+":"+id).hashCode() & 0x7fffffff;}
 static PendingIntent pending(Context c,int id,String title){Intent i=new Intent(c,AlarmReceiver.class).setAction(ACTION).putExtra("title",title).putExtra("id",id);return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void scheduleAll(Context c){try{String data=c.getSharedPreferences("data",0).getString("plan",null);if(data==null)return;JSONObject plan=new JSONObject(data);JSONArray week=plan.getJSONArray("Elis");AlarmManager mgr=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int d=0;d<7;d++){JSONArray arr=week.getJSONArray(d);for(int j=0;j<arr.length();j++){JSONObject t=arr.getJSONObject(j);int id=idFor(d,t.optString("id"));PendingIntent pi=pending(c,id,t.optString("subject","Ders"));mgr.cancel(pi);if(!t.optBoolean("alarm",false))continue;String[] hm=t.getString("time").split(":");Calendar next=Calendar.getInstance();int calendarDay=((d+1)%7)+1;next.set(Calendar.DAY_OF_WEEK,calendarDay);next.set(Calendar.HOUR_OF_DAY,Integer.parseInt(hm[0]));next.set(Calendar.MINUTE,Integer.parseInt(hm[1]));next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);if(next.getTimeInMillis()<=System.currentTimeMillis())next.add(Calendar.DAY_OF_YEAR,7);if(Build.VERSION.SDK_INT>=31&&!mgr.canScheduleExactAlarms())continue;mgr.setAlarmClock(new AlarmManager.AlarmClockInfo(next.getTimeInMillis(),PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)),pi);}}}catch(Exception e){android.util.Log.e("DersAlarm","Schedule",e);}}
 @Override public void onReceive(Context c,Intent intent){if(!ACTION.equals(intent.getAction()))return;String title=intent.getStringExtra("title");Intent a=new Intent(c,AlarmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("title",title);PendingIntent full=PendingIntent.getActivity(c,intent.getIntExtra("id",0),a,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="ders_alarm";if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(channel,"Ders alarmları",NotificationManager.IMPORTANCE_HIGH);ch.setSound(null,null);nm.createNotificationChannel(ch);}Notification n=new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Ders zamanı: "+title).setContentText("Alarmı durdurmak için açın").setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setFullScreenIntent(full,true).setAutoCancel(true).build();nm.notify(intent.getIntExtra("id",0),n);try{c.startActivity(a);}catch(Exception ignored){}scheduleAll(c);}
}